const query = $input.item.json.callback_query || {};
const data = query.data || '';
const fromUser = query.from?.username ? `@${query.from.username}` : (query.from?.first_name || 'Admin');
const messageId = query.message?.message_id;
const chatId = query.message?.chat?.id || -1004373843373;

let querySql = '';
let responseText = '';

// 1. Limpieza de Filtro de Agua
if (data.startsWith('filter_cleaned:')) {
  const notifId = data.replace('filter_cleaned:', '');
  querySql = `INSERT INTO "FilterCleaningLog" (id, "cleanedAt", "nextDueAt", notes, "confirmedBy", source, "createdAt") VALUES (gen_random_uuid(), NOW(), NOW() + INTERVAL '2 days', 'Confirmado vía Telegram', '${fromUser}', 'TELEGRAM_BOT', NOW()); UPDATE "Notification" SET "readAt" = NOW(), status = 'READ'::"NotificationStatus" WHERE id = '${notifId}' OR type = 'MAINTENANCE_REMINDER';`;
  responseText = `\u200B\n*Mantenimiento de Filtro Registrado*\n\nConfirmado por ${fromUser}\nPróxima limpieza programada en 48 horas.`;
}
// 2. Dosificación Manual Completada (DosingLog)
else if (data.startsWith('dosing_manual_confirm:')) {
  const parts = data.replace('dosing_manual_confirm:', '').split(':');
  const dosingLogId = parts[0];
  const notifId = parts[1] || '';
  const notifUpdate = notifId ? `UPDATE "Notification" SET "readAt" = NOW(), status = 'READ'::"NotificationStatus" WHERE id = '${notifId}';` : '';
  querySql = `UPDATE "DosingLog" SET status = 'COMPLETED'::"TaskStatus", "executedAt" = NOW() WHERE id = '${dosingLogId}'; ${notifUpdate}`;
  responseText = `\u200B\n*Dosificación Manual Completada*\n\nMarcada como realizada por ${fromUser}`;
}
// 3. Confirmación Tanque Hardware (TaskLog -> AUTHORIZED)
else if (data.startsWith('agro_hw_confirm:')) {
  const parts = data.replace('agro_hw_confirm:', '').split(':');
  const taskId = parts[0];
  const notifId = parts[1] || '';
  querySql = `UPDATE "TaskLog" SET status = 'AUTHORIZED'::"TaskStatus" WHERE id = '${taskId}'; UPDATE "Notification" SET "readAt" = NOW(), status = 'READ'::"NotificationStatus" WHERE id = '${notifId}';`;
  responseText = `\u200B\n*Tanque Confirmado y Autorizado*\n\nConfirmado por ${fromUser}\nEl riego de agroquímicos se ejecutará a la hora programada.`;
}
// 4. Posponer Tanque Hardware
else if (data.startsWith('agro_hw_postpone:')) {
  const parts = data.replace('agro_hw_postpone:', '').split(':');
  const taskId = parts[0];
  const hours = parseInt(parts[1] || '24', 10);
  const notifId = parts[2] || '';
  querySql = `UPDATE "TaskLog" SET "scheduledAt" = "scheduledAt" + INTERVAL '${hours} hours' WHERE id = '${taskId}'; UPDATE "Notification" SET "readAt" = NOW(), status = 'READ'::"NotificationStatus" WHERE id = '${notifId}';`;
  responseText = `\u200B\n*Riego Pospuesto ${hours} Horas*\n\nPospuesto por ${fromUser}`;
}
// 5. Cancelar Tanque Hardware
else if (data.startsWith('agro_hw_cancel:')) {
  const parts = data.replace('agro_hw_cancel:', '').split(':');
  const taskId = parts[0];
  const notifId = parts[1] || '';
  querySql = `UPDATE "TaskLog" SET status = 'CANCELLED'::"TaskStatus" WHERE id = '${taskId}'; UPDATE "Notification" SET "readAt" = NOW(), status = 'READ'::"NotificationStatus" WHERE id = '${notifId}';`;
  responseText = `\u200B\n*Riego Cancelado*\n\nCancelado por ${fromUser}`;
}
// 6. Legacy confirm_/cancel_
else if (data.startsWith('confirm_')) {
  const taskId = data.replace('confirm_', '');
  querySql = `UPDATE "DosingLog" SET status = 'COMPLETED'::"TaskStatus", "executedAt" = NOW() WHERE id = '${taskId}';`;
  responseText = `\u200B\n*Tarea Confirmada*\n\nRegistrada por ${fromUser}`;
}
else if (data.startsWith('cancel_')) {
  const taskId = data.replace('cancel_', '');
  querySql = `UPDATE "DosingLog" SET status = 'CANCELLED'::"TaskStatus" WHERE id = '${taskId}';`;
  responseText = `\u200B\n*Tarea Cancelada*\n\nPor ${fromUser}`;
}

if (!querySql) {
  return [];
}

return [{ json: { querySql, responseText, messageId, chatId } }];
